1	"use client";
2	
3	import { useMemo, useState } from "react";
4	
5	import { AlertCircle, LayoutDashboard } from "lucide-react";
6	import { useTranslations } from "next-intl";
7	import {
8	  Bar,
9	  BarChart,
10	  Cell,
11	  LabelList,
12	  PolarAngleAxis,
13	  RadialBar,
14	  RadialBarChart,
15	  ResponsiveContainer,
16	  Tooltip,
17	  XAxis,
18	  YAxis,
19	} from "recharts";
20	
21	import { RoleGuard } from "@/components/common/role-guard";
22	import { BentoCard, BentoGrid } from "@/components/ui/bento";
23	import {
24	  useObservabilitySummary,
25	  useProjectSummary,
26	  useSeats,
27	} from "@/hooks/use-observability";
28	import { useProjects } from "@/hooks/use-projects";
29	import {
30	  ApiClientError,
31	  type ProjectResponse,
32	  type SeatObservabilityEntry,
33	} from "@/lib/api-client";
34	
35	function isFeatureDisabled(error: unknown): boolean {
36	  return error instanceof ApiClientError && error.status === 404;
37	}
38	
39	/** 실존 상태값(project: active/archived/deleted, intake: pending_review/accepted/rejected) → 색.
40	 * 알려지지 않은 상태값은 muted 로 안전 폴백한다. */
41	const STATUS_COLORS: Record<string, string> = {
42	  active: "var(--accent)",
43	  archived: "var(--text-muted)",
44	  deleted: "var(--chart-danger)",
45	  pending_review: "var(--chart-warning)",
46	  accepted: "var(--chart-info)",
47	  rejected: "var(--text-muted)",
48	};
49	
50	const KNOWN_STATUS_KEYS = new Set(Object.keys(STATUS_COLORS));
51	
52	function colorFor(key: string): string {
53	  return STATUS_COLORS[key] ?? "var(--text-muted)";
54	}
55	
56	/** 상태 라벨 i18n — 실존 6개 상태값만 번역 커버, 미지 값은 원래 key로 폴백 */
57	function statusLabel(
58	  t: ReturnType<typeof useTranslations>,
59	  key: string,
60	): string {
61	  return KNOWN_STATUS_KEYS.has(key) ? t(`status.${key}`) : key;
62	}
63	
64	interface StatusTooltipProps {
65	  active?: boolean;
66	  payload?: Array<{ payload: { key: string; value: number; pct: number } }>;
67	  t: ReturnType<typeof useTranslations>;
68	}
69	
70	function StatusTooltip({ active, payload, t }: StatusTooltipProps) {
71	  if (!active || !payload || payload.length === 0) return null;
72	  const { key, value, pct } = payload[0].payload;
73	  return (
74	    <div className="rounded-lg border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-3 py-2 text-sm shadow-lg">
75	      <p className="font-semibold text-[var(--text-primary)]">
76	        {statusLabel(t, key)}
77	      </p>
78	      <p className="tabular-nums text-[var(--text-secondary)]">
79	        {value} ({pct}%)
80	      </p>
81	    </div>
82	  );
83	}
84	
85	/** 프로젝트 개별 상세(hover) — 토큰 합계·활동 기간·사용 계정 목록. CE-402 summary API 소비. */
86	function ProjectDetailCard({ projectId }: { projectId: string }) {
87	  const t = useTranslations("observability.dashboard.projectDetail");
88	  const { data, isLoading, error } = useProjectSummary(projectId, true);
89	
90	  if (isLoading) {
91	    return <p className="text-xs text-[var(--text-muted)]">{t("loading")}</p>;
92	  }
93	  if (error || !data) {
94	    return <p className="text-xs text-[var(--text-muted)]">{t("error")}</p>;
95	  }
96	
97	  const accounts = data.seats
98	    .map((s) => s.account_email)
99	    .filter((email): email is string => !!email);
100	
101	  return (
102	    <div className="mt-2 space-y-1.5 rounded-lg border border-[var(--border-subtle)] bg-[var(--bg-hover)] p-2.5 text-xs">
103	      <p className="text-[var(--text-secondary)]">
104	        {t("tokens")}:{" "}
105	        <span className="tabular-nums font-medium text-[var(--text-primary)]">
106	          {data.total_input_tokens + data.total_output_tokens}
107	        </span>
108	      </p>
109	      <p className="text-[var(--text-secondary)]">
110	        {t("period")}:{" "}
111	        <span className="text-[var(--text-primary)]">
112	          {data.first_activity_at
113	            ? new Date(data.first_activity_at).toLocaleDateString("ko-KR")
114	            : "—"}
115	          {" ~ "}
116	          {data.last_activity_at
117	            ? new Date(data.last_activity_at).toLocaleDateString("ko-KR")
118	            : "—"}
119	        </span>
120	      </p>
121	      <p className="text-[var(--text-secondary)]">
122	        {t("accounts")}:{" "}
123	        <span className="text-[var(--text-primary)]">
124	          {accounts.length > 0 ? accounts.join(", ") : t("accountsPending")}
125	        </span>
126	      </p>
127	    </div>
128	  );
129	}
130	
131	/** 상태별 프로젝트 목록(클릭 시 펼침) + 항목 hover 시 상세 카드.
132	 * projects_by_status 는 상태별 합계값만 가지고 있어 project_id 를 포함하지 않으므로,
133	 * 이미 존재하는 useProjects() 목록(id 포함)과 클라이언트에서 상태로 매칭해 사용한다(신규 API 없음).
134	 * deleted 상태는 프로젝트 목록 API 가 반환하지 않아(soft-delete 제외) 매칭 불가 — noList 안내로 폴백. */
135	function ProjectStatusList({
136	  statusKey,
137	  projects,
138	  isLoading,
139	}: {
140	  statusKey: string;
141	  projects: ProjectResponse[] | undefined;
142	  isLoading: boolean;
143	}) {
144	  const t = useTranslations("observability.dashboard.projectDetail");
145	  const [hoveredId, setHoveredId] = useState<string | null>(null);
146	  const matched = (projects ?? []).filter((p) => p.status === statusKey);
147	
148	  if (isLoading) {
149	    return <p className="mt-2 text-xs text-[var(--text-muted)]">{t("loading")}</p>;
150	  }
151	
152	  if (matched.length === 0) {
153	    return <p className="mt-2 text-xs text-[var(--text-muted)]">{t("noList")}</p>;
154	  }
155	
156	  return (
157	    <div className="mt-2 space-y-1">
158	      {matched.map((p) => (
159	        <div key={p.id}>
160	          <button
161	            type="button"
162	            onMouseEnter={() => setHoveredId(p.id)}
163	            onMouseLeave={() => setHoveredId((cur) => (cur === p.id ? null : cur))}
164	            onFocus={() => setHoveredId(p.id)}
165	            className="w-full rounded-md px-2 py-1 text-left text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-hover)]"
166	          >
167	            {p.name}
168	          </button>
169	          {hoveredId === p.id && <ProjectDetailCard projectId={p.id} />}
170	        </div>
171	      ))}
172	    </div>
173	  );
174	}
175	
176	function StatusBarChart({
177	  data,
178	  emptyLabel,
179	  interactive,
180	  allProjects,
181	  projectsLoading,
182	}: {
183	  data: Record<string, number>;
184	  emptyLabel: string;
185	  interactive?: boolean;
186	  allProjects?: ProjectResponse[];
187	  projectsLoading?: boolean;
188	}) {
189	  const t = useTranslations("observability.dashboard");
190	  const [selectedStatus, setSelectedStatus] = useState<string | null>(null);
191	  const entries = Object.entries(data);
192	  const total = entries.reduce((sum, [, v]) => sum + v, 0);
193	
194	  const chartData = useMemo(
195	    () =>
196	      entries.map(([key, value]) => ({
197	        key,
198	        value,
199	        pct: total > 0 ? Math.round((value / total) * 100) : 0,
200	      })),
201	    [entries, total],
202	  );
203	
204	  if (entries.length === 0 || total === 0) {
205	    return <p className="text-sm text-[var(--text-muted)]">{emptyLabel}</p>;
206	  }
207	
208	  return (
209	    <div className="mt-4">
210	      <ResponsiveContainer width="100%" height={chartData.length * 44 + 16}>
211	        <BarChart
212	          data={chartData}
213	          layout="vertical"
214	          margin={{ top: 4, right: 32, left: 0, bottom: 4 }}
215	        >
216	          <XAxis type="number" hide domain={[0, total]} />
217	          <YAxis
218	            type="category"
219	            dataKey="key"
220	            width={92}
221	            axisLine={false}
222	            tickLine={false}
223	            tick={{ fontSize: 14, fill: "var(--text-secondary)" }}
224	            tickFormatter={(key: string) => statusLabel(t, key)}
225	          />
226	          <Tooltip
227	            content={<StatusTooltip t={t} />}
228	            cursor={{ fill: "var(--bg-hover)" }}
229	          />
230	          <Bar
231	            dataKey="value"
232	            radius={[4, 4, 4, 4]}
233	            barSize={18}
234	            isAnimationActive
235	            animationDuration={500}
236	            onClick={(entry: unknown) => {
237	              const key = (entry as { payload?: { key?: string } } | undefined)?.payload
238	                ?.key;
239	              if (!interactive || !key) return;
240	              setSelectedStatus((cur) => (cur === key ? null : key));
241	            }}
242	            cursor={interactive ? "pointer" : undefined}
243	          >
244	            {chartData.map((entry) => (
245	              <Cell key={entry.key} fill={colorFor(entry.key)} />
246	            ))}
247	            <LabelList
248	              dataKey="value"
249	              position="right"
250	              style={{
251	                fill: "var(--text-muted)",
252	                fontSize: 14,
253	                fontWeight: 600,
254	              }}
255	            />
256	          </Bar>
257	        </BarChart>
258	      </ResponsiveContainer>
259	
260	      {interactive && (
261	        <>
262	          <p className="mt-2 text-xs text-[var(--text-muted)]">
263	            {t("projectDetail.hint")}
264	          </p>
265	          {selectedStatus && (
266	            <ProjectStatusList
267	              statusKey={selectedStatus}
268	              projects={allProjects}
269	              isLoading={!!projectsLoading}
270	            />
271	          )}
272	        </>
273	      )}
274	    </div>
275	  );
276	}
277	
278	function SuccessRateDonut({
279	  rate,
280	  successCount,
281	  failureCount,
282	}: {
283	  rate: number | null;
284	  successCount: number;
285	  failureCount: number;
286	}) {
287	  const t = useTranslations("observability.dashboard");
288	  const pct = rate !== null ? Math.round(rate * 100) : null;
289	
290	  if (pct === null && successCount === 0 && failureCount === 0) {
291	    return <p className="text-xs text-[var(--text-muted)]">{t("noRuns")}</p>;
292	  }
293	
294	  const displayPct = pct ?? 0;
295	
296	  return (
297	    <div className="mt-4 flex items-center gap-5">
298	      <div
299	        className="relative h-24 w-24 shrink-0 rounded-full"
300	        style={{
301	          background: `conic-gradient(var(--accent) ${displayPct}%, var(--bg-hover) ${displayPct}% 100%)`,
302	        }}
303	        role="img"
304	        aria-label={t("successRateAria", { pct: displayPct })}
305	      >
306	        <div className="absolute inset-2 flex items-center justify-center rounded-full bg-[var(--bg-surface)]">
307	          <span className="text-lg font-semibold tabular-nums text-[var(--text-primary)]">
308	            {pct !== null ? `${pct}%` : "—"}
309	          </span>
310	        </div>
311	      </div>
312	      <div className="space-y-1 text-xs">
313	        <p className="flex items-center gap-2">
314	          <span className="h-2 w-2 rounded-full bg-emerald-500" />
315	          <span className="text-[var(--text-secondary)]">
316	            {t("success")}: <span className="tabular-nums">{successCount}</span>
317	          </span>
318	        </p>
319	        <p className="flex items-center gap-2">
320	          <span className="h-2 w-2 rounded-full bg-red-500" />
321	          <span className="text-[var(--text-secondary)]">
322	            {t("failure")}: <span className="tabular-nums">{failureCount}</span>
323	          </span>
324	        </p>
325	      </div>
326	    </div>
327	  );
328	}
329	
330	/** 리셋까지 남은 시간 — 일/시간 단위 조각(초 단위 실시간 갱신 없음). resets_at 파싱 실패 시 null. */
331	function formatRemaining(resetsAt: string): { days: number; hours: number } | null {
332	  const diffMs = new Date(resetsAt).getTime() - Date.now();
333	  if (Number.isNaN(diffMs) || diffMs <= 0) return { days: 0, hours: 0 };
334	  const totalHours = Math.floor(diffMs / (1000 * 60 * 60));
335	  return { days: Math.floor(totalHours / 24), hours: totalHours % 24 };
336	}
337	
338	/** 계정별 잔량 게이지 — 5h/7d 비스코프 윈도우는 라디얼 게이지, 모델 스코프 윈도우는 선형 바.
339	 * CE-405: GET /observability/seats(기존, 무변경)만 소비. */
340	export function SeatBalanceGauges({ items }: { items: SeatObservabilityEntry[] }) {
341	  const t = useTranslations("observability.dashboard");
342	
343	  if (items.length === 0) {
344	    return <p className="mt-4 text-xs text-[var(--text-muted)]">{t("seatBalance.empty")}</p>;
345	  }
346	
347	  return (
348	    <div className="mt-4 space-y-4">
349	      {items.map((entry) => {
350	        const primaryWindows = entry.windows.filter(
351	          (w) => (w.window === "5h" || w.window === "7d") && w.scope_name === null,
352	        );
353	        const scopedWindows = entry.windows.filter((w) => w.scope_name !== null);
354	        const resetWindow =
355	          entry.windows.find((w) => w.window === "7d" && w.resets_at) ??
356	          entry.windows.find((w) => w.resets_at);
357	        const riskWindow = entry.windows.find(
358	          (w) => w.projected_exhaustion_at && w.will_last_to_reset === false,
359	        );
360	
361	        return (
362	          <div
363	            key={entry.account_email}
364	            className="rounded-xl border border-[var(--border-subtle)] bg-[var(--bg-hover)] p-3"
365	          >
366	            <div className="flex items-center justify-between gap-2">
367	              <p className="text-sm font-medium text-[var(--text-primary)]">
368	                {entry.account_email}
369	              </p>
370	              {riskWindow && (
371	                <span
372	                  className="rounded-full border px-2 py-0.5 text-xs"
373	                  style={{ borderColor: "var(--chart-danger)", color: "var(--chart-danger)" }}
374	                >
375	                  {t("seatBalance.exhaustionRisk")}
376	                </span>
377	              )}
378	            </div>
379	
380	            <div className="mt-3 flex flex-wrap gap-4">
381	              {primaryWindows.map((w) => {
382	                const pct = Math.min(100, Math.max(0, Number(w.pct) || 0));
383	                return (
384	                  <div key={w.window} className="relative h-20 w-20">
385	                    <ResponsiveContainer width="100%" height="100%">
386	                      <RadialBarChart
387	                        innerRadius="70%"
388	                        outerRadius="100%"
389	                        barSize={8}
390	                        data={[{ pct }]}
391	                        startAngle={90}
392	                        endAngle={-270}
393	                      >
394	                        <PolarAngleAxis type="number" domain={[0, 100]} tick={false} />
395	                        <RadialBar
396	                          dataKey="pct"
397	                          fill="var(--accent)"
398	                          background={{ fill: "var(--bg-hover)" }}
399	                          cornerRadius={4}
400	                        />
401	                      </RadialBarChart>
402	                    </ResponsiveContainer>
403	                    <div className="absolute inset-0 flex flex-col items-center justify-center">
404	                      <span className="text-xs font-semibold tabular-nums text-[var(--text-primary)]">
405	                        {pct}%
406	                      </span>
407	                      <span className="text-[10px] text-[var(--text-muted)]">{w.window}</span>
408	                    </div>
409	                  </div>
410	                );
411	              })}
412	            </div>
413	
414	            {scopedWindows.length > 0 && (
415	              <div className="mt-3 space-y-1.5">
416	                {scopedWindows.map((w) => {
417	                  const pct = Math.min(100, Math.max(0, Number(w.pct) || 0));
418	                  const color =
419	                    pct >= 90
420	                      ? "var(--chart-danger)"
421	                      : pct >= 70
422	                        ? "var(--chart-warning)"
423	                        : "var(--chart-info)";
424	                  return (
425	                    <div key={`${w.window}-${w.scope_name}`} className="text-xs">
426	                      <div className="mb-1 flex items-center justify-between">
427	                        <span className="text-[var(--text-secondary)]">{w.scope_name}</span>
428	                        <span className="tabular-nums text-[var(--text-muted)]">{pct}%</span>
429	                      </div>
430	                      <div className="h-2 w-full overflow-hidden rounded-full bg-[var(--bg-hover)]">
431	                        <div
432	                          className="h-full rounded-full"
433	                          style={{ width: `${pct}%`, backgroundColor: color }}
434	                        />
435	                      </div>
436	                    </div>
437	                  );
438	                })}
439	              </div>
440	            )}
441	
442	            {resetWindow?.resets_at &&
443	              (() => {
444	                const remaining = formatRemaining(resetWindow.resets_at);
445	                const value =
446	                  remaining.days > 0
447	                    ? `${remaining.days}${t("seatBalance.unitDay")} ${remaining.hours}${t("seatBalance.unitHour")}`
448	                    : `${remaining.hours}${t("seatBalance.unitHour")}`;
449	                return (
450	                  <p className="mt-2 text-[10px] text-[var(--text-muted)]">
451	                    {t("seatBalance.resetsIn", { value })}
452	                  </p>
453	                );
454	              })()}
455	          </div>
456	        );
457	      })}
458	    </div>
459	  );
460	}
461	
462	/** 계정 사용 순위(24h) — 24h input+output 합산 내림차순. "last used" 컬럼은 스펙상 범위 외. */
463	export function SeatRankingTable({ items }: { items: SeatObservabilityEntry[] }) {
464	  const t = useTranslations("observability.dashboard");
465	
466	  if (items.length === 0) {
467	    return <p className="mt-4 text-xs text-[var(--text-muted)]">{t("seatRanking.empty")}</p>;
468	  }
469	
470	  const sorted = [...items].sort(
471	    (a, b) =>
472	      b.usage_24h_input_tokens +
473	      b.usage_24h_output_tokens -
474	      (a.usage_24h_input_tokens + a.usage_24h_output_tokens),
475	  );
476	
477	  return (
478	    <table className="mt-4 w-full text-sm">
479	      <thead>
480	        <tr className="border-b border-[var(--border-subtle)] text-left text-xs text-[var(--text-muted)]">
481	          <th className="py-1.5 pr-2 font-medium">{t("seatRanking.rank")}</th>
482	          <th className="py-1.5 pr-2 font-medium">{t("seatRanking.account")}</th>
483	          <th className="py-1.5 pr-2 text-right font-medium">{t("seatRanking.usage24h")}</th>
484	          <th className="py-1.5 text-right font-medium">{t("seatRanking.balance")}</th>
485	        </tr>
486	      </thead>
487	      <tbody>
488	        {sorted.map((entry, idx) => {
489	          const usage = entry.usage_24h_input_tokens + entry.usage_24h_output_tokens;
490	          const balanceWindow = entry.windows.find(
491	            (w) => w.window === "7d" && w.scope_name === null,
492	          );
493	          const balance = balanceWindow
494	            ? `${Math.round(Number(balanceWindow.pct) || 0)}%`
495	            : "—";
496	          return (
497	            <tr
498	              key={entry.account_email}
499	              className="border-b border-[var(--border-subtle)] last:border-b-0"
500	            >
501	              <td className="py-1.5 pr-2 tabular-nums text-[var(--text-muted)]">{idx + 1}</td>
502	              <td className="py-1.5 pr-2 text-[var(--text-secondary)]">
503	                {entry.account_email}
504	              </td>
505	              <td className="py-1.5 pr-2 text-right tabular-nums text-[var(--text-primary)]">
506	                {usage}
507	              </td>
508	              <td className="py-1.5 text-right tabular-nums text-[var(--text-primary)]">
509	                {balance}
510	              </td>
511	            </tr>
512	          );
513	        })}
514	      </tbody>
515	    </table>
516	  );
517	}
518	
519	function DashboardContent() {
520	  const t = useTranslations("observability.dashboard");
521	  const { data, isLoading, error } = useObservabilitySummary();
522	  // projects_by_status 는 상태별 합계만 제공(project_id 미포함) → hover 상세 목록을 위해
523	  // 이미 존재하는 프로젝트 목록(id 포함) API 를 함께 조회해 클라이언트에서 상태로 매칭한다.
524	  const { data: projectsData, isLoading: projectsLoading } = useProjects({
525	    limit: 100,
526	  });
527	  // CE-405: 계정 잔량/사용순위 위젯 — 기존 GET /observability/seats 재사용, 요약 데이터와 독립 로딩.
528	  const { data: seatsData, isLoading: seatsLoading, error: seatsError } = useSeats();
529	
530	  return (
531	    <div className="space-y-6">
532	      <div className="flex items-center gap-3">
533	        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--accent-soft)]">
534	          <LayoutDashboard className="h-5 w-5 text-[var(--accent)]" />
535	        </div>
536	        <div>
537	          <h1 className="text-2xl font-bold text-[var(--text-primary)]">
538	            {t("pageTitle")}
539	          </h1>
540	          <p className="mt-0.5 text-sm text-[var(--text-muted)]">
541	            {t("pageDescription")}
